dashboard.definition:
{
  "title": "Wazuh - GitHub - Panel - Drilldown repository dashboard",
  "description": "GitHub - Panel - Drilldown repository dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer. Pick the repository in the Repository input, as the Wazuh dashboard does.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_scope": {
      "type": "input.dropdown",
      "title": "Repository",
      "dataSources": {
        "primary": "ds_input_01"
      },
      "options": {
        "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
        "token": "scope",
        "defaultValue": "*"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "formattedStatics": ">statics | formatByType(formattedConfig)",
        "statics": [
          [
            "All"
          ],
          [
            "*"
          ]
        ],
        "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_input_01": {
      "type": "ds.search",
      "name": "Repository",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"github\" \"url.original\"=* | eval value='url.original' | stats count by value | sort - count | head 500 | eval label=value | fields label, value"
      }
    },
    "ds_01": {
      "type": "ds.search",
      "name": "Top 10 actions",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"github\" \"url.original\"=$scope|s$ | eval f1='event.action' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"Actions\", metric as \"Count\""
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "Top 10 actors",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"github\" \"url.original\"=$scope|s$ | eval f1='user.name' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"Actors\", metric as \"Count\""
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Top 10 organizations",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"github\" \"url.original\"=$scope|s$ | eval f1='organization.name' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"Organizations\", metric as \"Count\""
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "Top 10 source IPs",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"github\" \"url.original\"=$scope|s$ | eval f1='source.ip' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"Source IPs\", metric as \"Count\""
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "Audit level evolution",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"github\" \"url.original\"=$scope|s$ | eval f1='wazuh.rule.level' | timechart span=1d useother=f usenull=f limit=10 count by f1"
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.pie",
      "title": "Top 10 actions",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_02": {
      "type": "splunk.pie",
      "title": "Top 10 actors",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_03": {
      "type": "splunk.pie",
      "title": "Top 10 organizations",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_04": {
      "type": "splunk.pie",
      "title": "Top 10 source IPs",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_05": {
      "type": "splunk.area",
      "title": "Audit level evolution",
      "dataSources": {
        "primary": "ds_05"
      },
      "options": {
        "stackMode": "stacked"
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 456,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp",
      "input_scope"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 396,
          "h": 216
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 400,
          "y": 0,
          "w": 396,
          "h": 216
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 800,
          "y": 0,
          "w": 396,
          "h": 216
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 0,
          "y": 220,
          "w": 596,
          "h": 216
        }
      },
      {
        "item": "viz_05",
        "type": "block",
        "position": {
          "x": 600,
          "y": 220,
          "w": 596,
          "h": 216
        }
      }
    ]
  }
}
